"""Agent tool registry.

One ``@tool`` declaration per tool is the single source of truth for:

* Lambda dispatch (:func:`fast_channels.functions.tools.dispatch.handler`),
* AgentCore Gateway tool schemas (:func:`gateway_tool_schema`),
* Cedar policies, the human-approval list and the console allow-list (generated by the infra package),
* the tool reference table in ``docs/agent.md``.

Tools are grouped by Gateway *target* (one Lambda per target). The Gateway exposes each tool to the agent as
``<target>___<name>`` (three underscores).
"""

import importlib
import inspect
from collections.abc import Callable, Iterator, Mapping
from dataclasses import dataclass
from enum import StrEnum
from typing import Any, Final, get_type_hints

from pydantic import BaseModel

TARGETS: Final = ("catalog", "library", "origins", "schedule", "channels", "encoding")
"""Gateway targets, in the order they are documented. Each maps to ``fast_channels.functions.tools.<target>``."""

SEPARATOR: Final = "___"
CORRELATION_FIELD: Final = "correlation_id"


class Access(StrEnum):
    """What a tool can do; drives Cedar authorisation by operator group."""

    READ = "read"
    WRITE = "write"
    DESTRUCTIVE = "destructive"


class Approval(StrEnum):
    """Whether the agent must obtain explicit human approval before calling the tool."""

    NONE = "none"
    CONFIRM = "confirm"


@dataclass(frozen=True, slots=True)
class ToolContext:
    """Per-invocation context handed to every tool implementation."""

    tool: str
    """Qualified tool name, e.g. ``schedule___publish``."""
    correlation_id: str
    """Agent session id (injected by the agent) or the Lambda request id."""


type ToolHandler[I: BaseModel, O: BaseModel] = Callable[[I, ToolContext], O]


@dataclass(frozen=True, slots=True)
class ToolSpec[I: BaseModel, O: BaseModel]:
    """Declaration of one agent tool."""

    target: str
    name: str
    description: str
    input: type[I]
    output: type[O]
    access: Access
    approval: Approval
    handler: ToolHandler[I, O]

    @property
    def qualified_name(self) -> str:
        return f"{self.target}{SEPARATOR}{self.name}"


class ToolError(Exception):
    """A tool failure the agent can reason about; serialised into the error envelope instead of raised."""

    def __init__(self, code: str, message: str, *, retryable: bool = False, hint: str = "") -> None:
        super().__init__(message)
        self.code = code
        self.message = message
        self.retryable = retryable
        self.hint = hint

    def envelope(self) -> dict[str, Any]:
        return {
            "ok": False,
            "error": {"code": self.code, "message": self.message, "retryable": self.retryable, "hint": self.hint},
        }


_REGISTRY: dict[str, dict[str, ToolSpec[Any, Any]]] = {target: {} for target in TARGETS}


def tool[I: BaseModel, O: BaseModel](
    target: str, *, access: Access, approval: Approval = Approval.NONE, name: str | None = None
) -> Callable[[ToolHandler[I, O]], ToolHandler[I, O]]:
    """Register a function ``(payload: Input, ctx: ToolContext) -> Output`` as an agent tool.

    The first parameter's annotation is the input model, the return annotation the output model and the docstring the
    description the model sees, so keep docstrings precise and action-oriented.
    """
    if target not in _REGISTRY:
        raise ValueError(f"unknown tool target {target!r}; expected one of {TARGETS}")

    def register(func: ToolHandler[I, O]) -> ToolHandler[I, O]:
        hints = get_type_hints(func)
        first = next(iter(inspect.signature(func).parameters))
        spec = ToolSpec(
            target=target,
            name=name or func.__name__,
            description=inspect.cleandoc(func.__doc__ or ""),
            input=hints[first],
            output=hints["return"],
            access=access,
            approval=approval,
            handler=func,
        )
        if not spec.description:
            raise ValueError(f"tool {spec.qualified_name} needs a docstring: it is the description the model reads")
        if spec.name in _REGISTRY[target]:
            raise ValueError(f"duplicate tool {spec.qualified_name}")
        _REGISTRY[target][spec.name] = spec
        return func

    return register


def load(target: str) -> Mapping[str, ToolSpec[Any, Any]]:
    """Import the target's module (registering its tools) and return its tools by short name."""
    importlib.import_module(f"fast_channels.functions.tools.{target}")
    return _REGISTRY[target]


def all_tools() -> Iterator[ToolSpec[Any, Any]]:
    """Every registered tool, in documentation order."""
    for target in TARGETS:
        yield from load(target).values()


def confirm_tools() -> list[str]:
    """Qualified names of tools that require human approval (passed to the agent as ``CONFIRM_TOOLS``)."""
    return [spec.qualified_name for spec in all_tools() if spec.approval is Approval.CONFIRM]


# --- AgentCore Gateway schema --------------------------------------------------------------------------------------
# Gateway tool schemas accept only type/properties/required/items/description, so constraints that JSON Schema would
# express (enum, bounds, formats, defaults) are folded into the description where the model can still read them.

_KEPT: Final = frozenset({"type", "properties", "required", "items", "description"})
_FOLDED: Final = {
    "enum": "one of {}",
    "const": "always {}",
    "default": "default {}",
    "minimum": "≥ {}",
    "maximum": "≤ {}",
    "exclusiveMinimum": "> {}",
    "exclusiveMaximum": "< {}",
    "minLength": "min length {}",
    "maxLength": "max length {}",
    "minItems": "at least {} items",
    "maxItems": "at most {} items",
    "pattern": "pattern {}",
    "format": "format {}",
}


def gateway_tool_schema(spec: ToolSpec[Any, Any]) -> dict[str, Any]:
    """The AgentCore Gateway Lambda-target tool definition for ``spec``."""
    schema = spec.input.model_json_schema()
    flat = _flatten(schema, schema.get("$defs", {}))
    flat.setdefault("properties", {})[CORRELATION_FIELD] = {
        "type": "string",
        "description": "Correlation id for tracing. Set automatically by the agent runtime; never invent one.",
    }
    return {"name": spec.name, "description": spec.description, "inputSchema": flat}


def _flatten(node: Mapping[str, Any], defs: Mapping[str, Any]) -> dict[str, Any]:
    if ref := node.get("$ref"):
        resolved = defs[ref.rsplit("/", 1)[-1]]
        return _flatten({**resolved, **{k: v for k, v in node.items() if k != "$ref"}}, defs)
    if variants := node.get("anyOf") or node.get("oneOf"):
        concrete = [v for v in variants if v.get("type") != "null"]
        merged = {**(concrete[0] if len(concrete) == 1 else {"type": "string"}), **_without(node, "anyOf", "oneOf")}
        return _flatten(merged, defs)
    if "allOf" in node and len(node["allOf"]) == 1:
        return _flatten({**node["allOf"][0], **_without(node, "allOf")}, defs)

    out: dict[str, Any] = {k: v for k, v in node.items() if k in _KEPT and k not in {"properties", "items"}}
    out.setdefault("type", "object" if "properties" in node else "string")
    notes = [template.format(_render(node[key])) for key, template in _FOLDED.items() if key in node]
    if notes or ("title" in node and "description" not in node):
        base = node.get("description") or node.get("title", "")
        out["description"] = "; ".join(filter(None, [base, *notes]))
    if properties := node.get("properties"):
        out["properties"] = {key: _flatten(value, defs) for key, value in properties.items()}
    if items := node.get("items"):
        out["items"] = _flatten(items, defs)
    return out


def _without(node: Mapping[str, Any], *keys: str) -> dict[str, Any]:
    return {k: v for k, v in node.items() if k not in keys}


def _render(value: Any) -> str:
    return ", ".join(map(str, value)) if isinstance(value, list) else str(value)
